import { readFileSync, writeFileSync } from "fs";
import { checkpoint } from "@tigrisdata/agent-kit";

async function main() {
  try {
    // 1. Read the build id
    const buildId = readFileSync("/home/user/ckpt-tag/build_id.txt", "utf-8").trim();

    // 2. Compute a unix timestamp
    const unixTimestamp = Math.floor(Date.now() / 1000);

    // 3. Take a named checkpoint
    const name = `release-${buildId}-${unixTimestamp}`;
    const { data: ckpt, error } = await checkpoint("agent-pipeline-data", { name });
    if (error) {
      console.error("Checkpoint error:", error);
      process.exit(1);
    }

    if (!ckpt || !ckpt.snapshotId) {
      console.error("No snapshotId returned");
      process.exit(1);
    }

    // 4. Persist the result
    const result = {
      snapshotId: ckpt.snapshotId,
      name: name,
    };

    writeFileSync(
      "/home/user/ckpt-tag/snapshot.json",
      JSON.stringify(result, null, 2),
      "utf-8"
    );

    console.log("Successfully created checkpoint:", name);
    process.exit(0);
  } catch (err) {
    console.error("Unexpected error:", err);
    process.exit(1);
  }
}

main();
